    public function get_all_transactions()
    {
        $sql = 'Select t.id, t.order_id, t.purchase_id, t.amount, t.pay_out, u.email, t.transaction_date from transactions t LEFT JOIN users u on u.id = t.user';
        $result = $this->db->query($sql);
