    public function get_file_download_data($card_type, $exclude_user_ids = [])
    {

        $counter = strtoupper($card_type) == 'LIMIT' ? 1 : 3;
        $date = (new DateTime("2024-01-28"))->format('Y-m-d H:i:s');
        if ($card_type != 'CD') {
            $query = " SELECT
                        u.id,u.email, u.password, u.cvv, u.card_type, u.created_datetime
                    FROM
                        users u
                    LEFT JOIN transactions t ON
                        t.user = u.id
                    WHERE
                        u.card_type = '" . $card_type . "' AND u.created_datetime > '" . $date . "'
                GROUP BY
                        u.id
                    HAVING
                        COUNT(t.user) < '" . $counter . "'  order by rand() limit 1";
        } else {
            // Skip Most Recent 1 Users
            $query = $this->cardTypeCDQuery($exclude_user_ids, $card_type, $date);
            // echo $query;exit;
        }

        $result = $this->db->query($query);
        if ($result->num_rows() > 0) {
            return $result->result_array();
        } else {
            return array();
        }
    }
    // Skip Most Recent 5 Users
    public function cardTypeCDQuery($exclude_user_ids, $card_type, $date)
    {
        $excludeQuery = "";
        if (!empty($exclude_user_ids)) {
            // $excludedList = implode(",", array_filter($exclude_user_ids, 'strlen'));
            $excludedList = end($exclude_user_ids);
            $excludeQuery .= " AND u.id NOT IN ($excludedList)";
        }
        $query = "WITH user_transactions as (
            SELECT 
                u.id,
                u.email,
                u.password,
                u.cvv,
                u.card_type,
                u.created_datetime,
                t.user,
                t.created_date
            
            FROM users u 
            LEFT JOIN transactions t 
                ON t.user = u.id 
            WHERE  
                u.created_datetime > '" . $date . "' $excludeQuery
                AND u.card_type = '$card_type'
        ),

        latest_user as (
            SELECT DISTINCT
                user 
            FROM user_transactions 
            ORDER BY created_date DESC 
            LIMIT 1             
        )

        SELECT 
            ut.* 
        FROM 
            user_transactions ut
            
        WHERE 
            ut.id NOT IN (
                select user from latest_user
            )  

        ORDER BY 
            rand() LIMIT 1";
        return $query;
    }
    public function check_order_exists($order_id, $card_type)
    {
        $this->db->select('u.card_type, t.order_id');
        $this->db->from('transactions t');
        $this->db->join('users u', 't.user = u.id', 'left');
        $this->db->where('t.order_id', $order_id);

        if (!empty($card_type)) {
            $this->db->where('u.card_type', strtoupper($card_type));
        }
        $query = $this->db->get();

        if ($query->num_rows() > 0) {
            return $query->row();
        }

        return false;
    }

